#include <chrono>

namespace duckdb {

class UnscentedKalmanFilter {
private:
	static constexpr size_t STATE_DIM = 2; // [progress, velocity]
	static constexpr size_t OBS_DIM = 1;   // [progress]
	static constexpr size_t SIGMA_POINTS = 2 * STATE_DIM + 1;

	// UKF parameters
	static constexpr double ALPHA = 0.044;
	static constexpr double BETA = 1.0;
	static constexpr double KAPPA = 0.0;

	double lambda;
	vector<double> wm, wc; // weights for mean and covariance

	// State: [progress (0-1), velocity (progress/second)]
	vector<double> x;         // state estimate
	vector<vector<double>> P; // covariance matrix
	vector<vector<double>> Q; // process noise
	vector<vector<double>> R; // measurement noise

	double last_time;
	bool initialized;
	double last_progress;
	double scale_factor;

	// Helper functions
	vector<vector<double>> MatrixSqrt(const vector<vector<double>> &mat);
	vector<vector<double>> GenerateSigmaPoints();
	vector<double> StateTransition(const vector<double> &state, double dt);
	vector<double> MeasurementFunction(const vector<double> &state);

public:
	UnscentedKalmanFilter();

	void Update(double progress, double time);

	double GetEstimatedRemainingSeconds() const;

private:
	void Initialize(double initial_progress, double current_time);
	void Predict(double current_time);
	void UpdateInternal(double measured_progress);

	double GetProgress() const;
	double GetVelocity() const;
	double GetProgressVariance() const;
	double GetVelocityVariance() const;
};

} // namespace duckdb

#include <chrono>

namespace duckdb {

struct TerminalProgressBarDisplayedProgressInfo {
	optional_idx percentage;
	optional_idx estimated_seconds_remaining;

	bool operator==(const TerminalProgressBarDisplayedProgressInfo &other) const {
		return percentage == other.percentage && estimated_seconds_remaining == other.estimated_seconds_remaining;
	}

	bool operator!=(const TerminalProgressBarDisplayedProgressInfo &other) const {
		return !(*this == other);
	}
};

struct ProgressBarDisplayInfo {
	idx_t width = 38;
#ifndef DUCKDB_ASCII_TREE_RENDERER
	const char *progress_empty = " ";
	const char *const *progress_partial = UnicodeBar::PartialBlocks();
	idx_t partial_block_count = UnicodeBar::PartialBlocksCount();
	const char *progress_block = UnicodeBar::FullBlock();
	const char *progress_start = "\xE2\x96\x95";
	const char *progress_end = "\xE2\x96\x8F";
#else
	const char *progress_empty = " ";
	const char *const progress_partial[PARTIAL_BLOCK_COUNT] = {" ", " ", " ", " ", " ", " ", " ", " "};
	idx_t partial_block_count = 8;
	const char *progress_block = "=";
	const char *progress_start = "[";
	const char *progress_end = "]";
#endif
};

class TerminalProgressBarDisplay : public ProgressBarDisplay {
public:
	TerminalProgressBarDisplay() {
		start_time = std::chrono::steady_clock::now();
		displayed_progress_info = {optional_idx(), optional_idx()};
	}

	~TerminalProgressBarDisplay() override {
	}

public:
	void Update(double percentage) override;
	void Finish() override;
	static string FormatETA(double seconds, bool elapsed = false);
	static string FormatProgressBar(const ProgressBarDisplayInfo &display_info, int32_t percentage);

private:
	void PeriodicUpdate();

public:
	ProgressBarDisplayInfo display_info;

protected:
	virtual void PrintProgressInternal(int32_t percentage, double estimated_remaining_seconds,
	                                   bool is_finished = false);

	static int32_t NormalizePercentage(double percentage);
	double GetElapsedDuration() {
		auto now = std::chrono::steady_clock::now();
		return std::chrono::duration<double>(now - start_time).count();
	}
	void StopPeriodicUpdates();

private:
	UnscentedKalmanFilter ukf;
	std::chrono::steady_clock::time_point start_time;

	// track the progress info that has been previously
	// displayed to prevent redundant updates
	struct TerminalProgressBarDisplayedProgressInfo displayed_progress_info;
};

} // namespace duckdb


namespace duckdb {

void QueryProgress::Initialize() {
	percentage = -1;
	rows_processed = 0;
	total_rows_to_process = 0;
}

void QueryProgress::Restart() {
	percentage = 0;
	rows_processed = 0;
	total_rows_to_process = 0;
}

double QueryProgress::GetPercentage() {
	return percentage;
}
uint64_t QueryProgress::GetRowsProcesseed() {
	return rows_processed;
}
uint64_t QueryProgress::GetTotalRowsToProcess() {
	return total_rows_to_process;
}

QueryProgress::QueryProgress() {
	Initialize();
}

QueryProgress &QueryProgress::operator=(const QueryProgress &other) {
	if (this != &other) {
		percentage = other.percentage.load();
		rows_processed = other.rows_processed.load();
		total_rows_to_process = other.total_rows_to_process.load();
	}
	return *this;
}

QueryProgress::QueryProgress(const QueryProgress &other) {
	percentage = other.percentage.load();
	rows_processed = other.rows_processed.load();
	total_rows_to_process = other.total_rows_to_process.load();
}

void ProgressBar::SystemOverrideCheck(ClientConfig &config) {
	if (config.system_progress_bar_disable_reason != nullptr) {
		throw InvalidInputException("Could not change the progress bar setting because: '%s'",
		                            config.system_progress_bar_disable_reason);
	}
}

unique_ptr<ProgressBarDisplay> ProgressBar::DefaultProgressBarDisplay() {
	return make_uniq<TerminalProgressBarDisplay>();
}

ProgressBar::ProgressBar(Executor &executor, idx_t show_progress_after,
                         const progress_bar_display_create_func_t &create_display_func)
    : executor(executor), show_progress_after(show_progress_after) {
	if (create_display_func) {
		display = create_display_func();
	}
}

QueryProgress ProgressBar::GetDetailedQueryProgress() {
	return query_progress;
}

void ProgressBar::Start() {
	profiler.Start();
	query_progress.Initialize();
	supported = true;
}

bool ProgressBar::PrintEnabled() const {
	return display != nullptr;
}

bool ProgressBar::ShouldPrint(bool final) const {
	if (!PrintEnabled()) {
		// Don't print progress at all
		return false;
	}
	if (!supported) {
		return false;
	}

	double elapsed_time = -1.0;
	if (elapsed_time < 0.0) {
		elapsed_time = profiler.Elapsed();
	}

	auto sufficient_time_elapsed = elapsed_time > static_cast<double>(show_progress_after) / 1000.0;
	if (!sufficient_time_elapsed) {
		// Don't print yet
		return false;
	}
	if (final) {
		// Print the last completed bar
		return true;
	}
	return query_progress.percentage > -1;
}

void ProgressBar::Update(bool final) {
	if (!final && !supported) {
		return;
	}

	ProgressData progress;
	idx_t invalid_pipelines = executor.GetPipelinesProgress(progress);

	double new_percentage = 0.0;
	if (invalid_pipelines == 0 && progress.IsValid()) {
		if (progress.total > 1e15) {
			progress.Normalize(1e15);
		}
		query_progress.rows_processed = idx_t(progress.done);
		query_progress.total_rows_to_process = idx_t(progress.total);
		new_percentage = progress.ProgressDone() * 100;
	}

	if (!final && invalid_pipelines > 0) {
		return;
	}

	if (new_percentage > query_progress.percentage) {
		query_progress.percentage = new_percentage;
	}
	if (ShouldPrint(final)) {
		if (final) {
			FinishProgressBarPrint();
		} else {
			PrintProgress(query_progress.percentage.load());
		}
	}
}

void ProgressBar::PrintProgress(double current_percentage_p) {
	D_ASSERT(display);
	display->Update(current_percentage_p);
}

void ProgressBar::FinishProgressBarPrint() {
	if (finished) {
		return;
	}
	D_ASSERT(display);
	display->Finish();
	finished = true;
	if (query_progress.percentage == 0) {
		query_progress.Initialize();
	}
}

} // namespace duckdb




namespace duckdb {

int32_t TerminalProgressBarDisplay::NormalizePercentage(double percentage) {
	if (percentage > 100) {
		return 100;
	}
	if (percentage < 0) {
		return 0;
	}
	return int32_t(percentage);
}

string TerminalProgressBarDisplay::FormatETA(double seconds, bool elapsed) {
	// for terminal rendering purposes, we need to make sure the length is always the same
	// we pad the end with spaces if that is not the case
	// the maximum length here is "(~10.35 minutes remaining)" (26 bytes)
	// always pad to this amount
	static constexpr idx_t RENDER_SIZE = 26;

	if (seconds < 0 || seconds == 2147483647) {
		// Invalid or unknown ETA, skip rendering estimate
		return string(RENDER_SIZE, ' ');
	}

	if (!elapsed && seconds > 3600 * 99) {
		// estimate larger than 99 hours remaining, treat this as invalid/unknown ETA
		return string(RENDER_SIZE, ' ');
	}

	// Round to nearest centisecond as integer
	auto total_centiseconds = static_cast<uint64_t>(std::llround(seconds * 100.0));

	// Split into seconds and centiseconds
	uint64_t total_seconds = total_centiseconds / 100;
	uint32_t centiseconds = static_cast<uint32_t>(total_centiseconds % 100);

	// Break down total_seconds
	uint64_t hours = total_seconds / 3600;
	uint32_t minutes = static_cast<uint32_t>((total_seconds % 3600) / 60);
	uint32_t secs = static_cast<uint32_t>(total_seconds % 60);
	string result;
	result = "(";
	if (!elapsed) {
		if (hours == 0 && minutes == 0 && secs == 0) {
			result += StringUtil::Format("<1 second");
		} else if (hours == 0 && minutes == 0) {
			result += StringUtil::Format("~%u second%s", secs, secs > 1 ? "s" : "");
		} else if (hours == 0) {
			auto minute_fraction = static_cast<uint32_t>(static_cast<double>(secs) / 60.0 * 10);
			result += StringUtil::Format("~%u.%u minutes", minutes, minute_fraction);
		} else {
			auto hour_fraction = static_cast<uint32_t>(static_cast<double>(minutes) / 60.0 * 10);
			result += StringUtil::Format("~%llu.%u hours", hours, hour_fraction);
		}
		result += " remaining";
	} else {
		result += StringUtil::Format("%02llu:%02u:%02u.%02llu", hours, minutes, secs, centiseconds);
		result += " elapsed";
	}
	result += ")";
	if (result.size() < RENDER_SIZE) {
		result += string(RENDER_SIZE - result.size(), ' ');
	}
	return result;
}

string TerminalProgressBarDisplay::FormatProgressBar(const ProgressBarDisplayInfo &display, int32_t percentage) {
	// we divide the number of blocks by the percentage
	// 0%   = 0
	// 100% = PROGRESS_BAR_WIDTH
	// the percentage determines how many blocks we need to draw
	double blocks_to_draw = static_cast<double>(display.width) * (percentage / 100.0);
	// because of the power of unicode, we can also draw partial blocks
	string result;
	result += display.progress_start;
	idx_t i;
	for (i = 0; i < idx_t(blocks_to_draw); i++) {
		result += display.progress_block;
	}
	if (i < display.width) {
		// print a partial block based on the percentage of the progress bar remaining
		idx_t index = idx_t((blocks_to_draw - static_cast<double>(idx_t(blocks_to_draw))) *
		                    static_cast<double>(display.partial_block_count));
		if (index >= display.partial_block_count) {
			index = display.partial_block_count - 1;
		}
		result += display.progress_partial[index];
		i++;
	}
	for (; i < display.width; i++) {
		result += display.progress_empty;
	}
	result += display.progress_end;
	return result;
}

void TerminalProgressBarDisplay::PrintProgressInternal(int32_t percentage, double seconds, bool finished) {
	string result;

	// render the percentage with some padding to ensure everything stays nicely aligned
	result = "\r";
	if (percentage < 100) {
		result += " ";
	}
	if (percentage < 10) {
		result += " ";
	}
	result += to_string(percentage) + "%";
	result += " ";
	result += FormatProgressBar(display_info, percentage);
	result += " ";
	result += FormatETA(seconds, finished);

	Printer::RawPrint(OutputStream::STREAM_STDOUT, result);
}

void TerminalProgressBarDisplay::Update(double percentage) {
	const double current_time = GetElapsedDuration();

	// Filters go from 0 to 1, percentage is from 0-100
	const double filter_percentage = percentage / 100.0;

	ukf.Update(filter_percentage, current_time);

	double estimated_seconds_remaining;
	//  If the query is mostly completed, there can be oscillation of estimated
	//  time to completion since the progress updates seem sparse near the very
	//  end of the query, so clamp time remaining to not oscillate with estimates
	//  that are unlikely to be correct.
	if (filter_percentage > 0.99) {
		estimated_seconds_remaining = 0.5;
	} else {
		estimated_seconds_remaining = std::min(ukf.GetEstimatedRemainingSeconds(), 2147483647.0);
	}
	auto percentage_int = NormalizePercentage(percentage);

	TerminalProgressBarDisplayedProgressInfo updated_progress_info = {(idx_t)percentage_int,
	                                                                  (idx_t)estimated_seconds_remaining};
	if (displayed_progress_info != updated_progress_info) {
		PrintProgressInternal(percentage_int, estimated_seconds_remaining);
		Printer::Flush(OutputStream::STREAM_STDOUT);
		displayed_progress_info = updated_progress_info;
	}
}

void TerminalProgressBarDisplay::Finish() {
	PrintProgressInternal(100, GetElapsedDuration(), true);
	Printer::RawPrint(OutputStream::STREAM_STDOUT, "\n");
	Printer::Flush(OutputStream::STREAM_STDOUT);
}

} // namespace duckdb


namespace duckdb {

UnscentedKalmanFilter::UnscentedKalmanFilter()
    : x(STATE_DIM, 0.0), P(STATE_DIM, vector<double>(STATE_DIM, 0.0)), Q(STATE_DIM, vector<double>(STATE_DIM, 0.0)),
      R(OBS_DIM, vector<double>(OBS_DIM, 0.0)), last_time(0.0), initialized(false), last_progress(-1.0),
      scale_factor(1.0) {
	// Calculate UKF parameters
	lambda = ALPHA * ALPHA * (STATE_DIM + KAPPA) - STATE_DIM;

	// Initialize weights
	wm.resize(SIGMA_POINTS);
	wc.resize(SIGMA_POINTS);

	wm[0] = lambda / (STATE_DIM + lambda);
	wc[0] = lambda / (STATE_DIM + lambda) + (1 - ALPHA * ALPHA + BETA);

	for (size_t i = 1; i < SIGMA_POINTS; i++) {
		wm[i] = wc[i] = 0.5 / (STATE_DIM + lambda);
	}

	// Initialize covariance matrices
	P[0][0] = 0.165;  // progress variance
	P[1][1] = 0.0098; // velocity variance

	Q[0][0] = 0.01; // process noise for progress
	Q[1][1] = 0.0;  // process noise for velocity

	R[0][0] = 0.000077; // measurement noise for progress
}

void UnscentedKalmanFilter::Update(double progress, double time) {
	progress *= scale_factor;
	if (!initialized) {
		Initialize(progress, time);
		return;
	}
	Predict(time);
	if (last_progress != progress) {
		UpdateInternal(progress);
		last_progress = progress;
	}
}

void UnscentedKalmanFilter::Initialize(double initial_progress, double current_time) {
	// If the initial progress is zero we can't yet initalize, since the filter
	// wont' have a reasonable guess about query velocity, just wait until some
	// progress has been made.
	if (initial_progress == 0.0 || current_time == 0.0) {
		return;
	}
	// If the initial progress value is very small, it needs to be scaled up so
	// its the same relative magnitude of updates that was used to determine
	// the P, Q, and R parameters of the Kalman filter.
	//
	// The settings for the Kalman filter make assumptions around the magnitude of
	// measurement noise.  If the progress updates are very small, the updates
	// could be considered noise by the Kalman filter.
	scale_factor = std::max(1.0, 0.1 / initial_progress);
	initial_progress *= scale_factor;
	x[0] = initial_progress;
	x[1] = initial_progress / current_time; // initial velocity guess
	last_time = current_time;
	last_progress = initial_progress;
	initialized = true;
}

// Matrix operations
vector<vector<double>> UnscentedKalmanFilter::MatrixSqrt(const vector<vector<double>> &mat) {
	size_t n = mat.size();
	vector<vector<double>> L(n, vector<double>(n, 0.0));

	// Cholesky decomposition
	for (size_t i = 0; i < n; i++) {
		for (size_t j = 0; j <= i; j++) {
			if (i == j) {
				double sum = 0;
				for (size_t k = 0; k < j; k++) {
					sum += L[j][k] * L[j][k];
				}
				L[j][j] = std::sqrt(mat[j][j] - sum);
			} else {
				double sum = 0;
				for (size_t k = 0; k < j; k++) {
					sum += L[i][k] * L[j][k];
				}
				L[i][j] = (mat[i][j] - sum) / L[j][j];
			}
		}
	}
	return L;
}

// Generate sigma points
vector<vector<double>> UnscentedKalmanFilter::GenerateSigmaPoints() {
	vector<vector<double>> sigma_points(SIGMA_POINTS, vector<double>(STATE_DIM));

	// Calculate sqrt((n + lambda) * P)
	auto scaled_P = P;
	double scale = STATE_DIM + lambda;
	for (size_t i = 0; i < STATE_DIM; i++) {
		for (size_t j = 0; j < STATE_DIM; j++) {
			scaled_P[i][j] *= scale;
		}
	}

	auto sqrt_P = MatrixSqrt(scaled_P);

	// First sigma point is the mean
	sigma_points[0] = x;

	// Remaining sigma points
	for (size_t i = 0; i < STATE_DIM; i++) {
		for (size_t j = 0; j < STATE_DIM; j++) {
			sigma_points[i + 1][j] = x[j] + sqrt_P[j][i];
			sigma_points[i + 1 + STATE_DIM][j] = x[j] - sqrt_P[j][i];
		}
	}

	return sigma_points;
}

// State transition function
vector<double> UnscentedKalmanFilter::StateTransition(const vector<double> &state, double dt) {
	vector<double> new_state(STATE_DIM);
	new_state[0] = state[0] + state[1] * dt; // progress += velocity * dt
	new_state[1] = state[1];                 // velocity remains constant

	// Clamp progress to [0, 1]
	new_state[0] = std::max(0.0, std::min(1.0, new_state[0]));

	return new_state;
}

// Measurement function (identity for progress)
vector<double> UnscentedKalmanFilter::MeasurementFunction(const vector<double> &state) {
	return {state[0]};
}

void UnscentedKalmanFilter::Predict(double current_time) {
	D_ASSERT(initialized);

	double dt = current_time - last_time;
	last_time = current_time;

	if (dt <= 0) {
		return;
	}

	// Generate sigma points
	auto sigma_points = GenerateSigmaPoints();

	// Propagate sigma points through state transition
	vector<vector<double>> sigma_points_pred(SIGMA_POINTS, vector<double>(STATE_DIM));
	for (size_t i = 0; i < SIGMA_POINTS; i++) {
		sigma_points_pred[i] = StateTransition(sigma_points[i], dt);
	}

	// Predict state mean
	std::fill(x.begin(), x.end(), 0.0);
	for (size_t i = 0; i < SIGMA_POINTS; i++) {
		for (size_t j = 0; j < STATE_DIM; j++) {
			x[j] += wm[i] * sigma_points_pred[i][j];
		}
	}

	// Predict covariance
	for (size_t i = 0; i < STATE_DIM; i++) {
		std::fill(P[i].begin(), P[i].end(), 0.0);
	}

	for (size_t i = 0; i < SIGMA_POINTS; i++) {
		for (size_t j = 0; j < STATE_DIM; j++) {
			for (size_t k = 0; k < STATE_DIM; k++) {
				P[j][k] += wc[i] * (sigma_points_pred[i][j] - x[j]) * (sigma_points_pred[i][k] - x[k]);
			}
		}
	}

	// Add process noise
	for (size_t i = 0; i < STATE_DIM; i++) {
		for (size_t j = 0; j < STATE_DIM; j++) {
			P[i][j] += Q[i][j];
		}
	}
}

void UnscentedKalmanFilter::UpdateInternal(double measured_progress) {
	D_ASSERT(initialized);
	// Generate sigma points
	auto sigma_points = GenerateSigmaPoints();

	// Transform sigma points through measurement function
	vector<vector<double>> Z_sigma(SIGMA_POINTS, vector<double>(OBS_DIM));
	for (size_t i = 0; i < SIGMA_POINTS; i++) {
		Z_sigma[i] = MeasurementFunction(sigma_points[i]);
	}

	// Predict measurement mean
	vector<double> z_pred(OBS_DIM, 0.0);
	for (size_t i = 0; i < SIGMA_POINTS; i++) {
		for (size_t j = 0; j < OBS_DIM; j++) {
			z_pred[j] += wm[i] * Z_sigma[i][j];
		}
	}

	// Innovation covariance
	vector<vector<double>> S(OBS_DIM, vector<double>(OBS_DIM, 0.0));
	for (size_t i = 0; i < SIGMA_POINTS; i++) {
		for (size_t j = 0; j < OBS_DIM; j++) {
			for (size_t k = 0; k < OBS_DIM; k++) {
				S[j][k] += wc[i] * (Z_sigma[i][j] - z_pred[j]) * (Z_sigma[i][k] - z_pred[k]);
			}
		}
	}

	// Add measurement noise
	for (size_t i = 0; i < OBS_DIM; i++) {
		for (size_t j = 0; j < OBS_DIM; j++) {
			S[i][j] += R[i][j];
		}
	}

	// Cross correlation
	vector<vector<double>> T(STATE_DIM, vector<double>(OBS_DIM, 0.0));
	for (size_t i = 0; i < SIGMA_POINTS; i++) {
		for (size_t j = 0; j < STATE_DIM; j++) {
			for (size_t k = 0; k < OBS_DIM; k++) {
				T[j][k] += wc[i] * (sigma_points[i][j] - x[j]) * (Z_sigma[i][k] - z_pred[k]);
			}
		}
	}

	// Kalman gain (simplified for 1D measurement)
	vector<vector<double>> K(STATE_DIM, vector<double>(OBS_DIM));
	double S_inv = 1.0 / S[0][0];
	for (size_t i = 0; i < STATE_DIM; i++) {
		K[i][0] = T[i][0] * S_inv;
	}

	// Update state
	vector<double> innovation = {measured_progress - z_pred[0]};
	for (size_t i = 0; i < STATE_DIM; i++) {
		x[i] += K[i][0] * innovation[0];
	}

	// Update covariance
	for (size_t i = 0; i < STATE_DIM; i++) {
		for (size_t j = 0; j < STATE_DIM; j++) {
			P[i][j] -= K[i][0] * S[0][0] * K[j][0];
		}
	}

	// Ensure progress stays in bounds
	x[0] = std::max(0.0, std::min(scale_factor, x[0]));
}

double UnscentedKalmanFilter::GetProgress() const {
	return x[0] / scale_factor;
}

double UnscentedKalmanFilter::GetVelocity() const {
	return x[1];
}

double UnscentedKalmanFilter::GetEstimatedRemainingSeconds() const {
	if (!initialized) {
		return 2147483647.0;
	}
	if (x[1] <= 0) {
		// velocity is negative or zero - we estimate this will never finish
		return NumericLimits<double>::Maximum();
	}
	double remaining_progress = (1.0 * scale_factor) - x[0];
	return std::max(remaining_progress / x[1], 0.0);
}

double UnscentedKalmanFilter::GetProgressVariance() const {
	return P[0][0];
}

double UnscentedKalmanFilter::GetVelocityVariance() const {
	return P[1][1];
}

} // namespace duckdb
