LogicalType LogicalType::UNBOUND(unique_ptr<ParsedExpression> expr) {
	auto info = make_shared_ptr<UnboundTypeInfo>(std::move(expr));
	return LogicalType(LogicalTypeId::UNBOUND, std::move(info));
}

