namespace duckdb {

//! PrefixHandle is a mutable wrapper to access and modify a prefix node.
//! The prefix contains up to the ART's prefix size bytes, an additional byte for the count,
//! and a Node pointer to a child node.
//! PrefixHandle uses SegmentHandle for memory management and marks memory as modified.
//! For read-only access, use ConstPrefixHandle instead.
class PrefixHandle {
public:
	static constexpr NType PREFIX = NType::PREFIX;
	static constexpr uint8_t DEPRECATED_COUNT = 15;

public:
	PrefixHandle() = delete;
	PrefixHandle(const ART &art, const Node node);
	PrefixHandle(FixedSizeAllocator &allocator, const Node node, const uint8_t count);
	PrefixHandle(const PrefixHandle &) = delete;
	PrefixHandle(PrefixHandle &&other) noexcept;
	PrefixHandle &operator=(PrefixHandle &&other) noexcept;

	data_ptr_t data;
	Node *child;

public:
	//! Create a new deprecated prefix node and return a handle to it.
	static PrefixHandle NewDeprecated(FixedSizeAllocator &allocator, Node &node);

	//! Transform prefix chain to deprecated format.
	//! nullptr denotes an early out optimization (the prefix has not been loaded from storage, hence we do not need
	//! to transform it. Otherwise, we get a pointer to the child node at the end of the prefix chain.
	static optional_ptr<Node> TransformToDeprecated(ART &art, Node &node, TransformToDeprecatedState &state);

private:
	PrefixHandle TransformToDeprecatedAppend(ART &art, FixedSizeAllocator &allocator, const uint8_t byte);

private:
	SegmentHandle segment_handle;
};

} // namespace duckdb



namespace duckdb {

//===--------------------------------------------------------------------===//
// New and free
//===--------------------------------------------------------------------===//

void Node::New(ART &art, Node &node, NType type) {
	switch (type) {
	case NType::NODE_7_LEAF:
		Node7Leaf::New(art, node);
		break;
	case NType::NODE_15_LEAF:
		Node15Leaf::New(art, node);
		break;
	case NType::NODE_256_LEAF:
		Node256Leaf::New(art, node);
		break;
	case NType::NODE_4:
		Node4::New(art, node);
		break;
	case NType::NODE_16:
		Node16::New(art, node);
		break;
	case NType::NODE_48:
		Node48::New(art, node);
		break;
	case NType::NODE_256:
		Node256::New(art, node);
		break;
	default:
		throw InternalException("Invalid node type for New: %d.", type);
	}
}

void Node::FreeNode(ART &art, Node &node) {
	D_ASSERT(node.HasMetadata());
	GetAllocator(art, node.GetType()).Free(node);
	node.Clear();
}

void Node::FreeTree(ART &art, Node &node) {
	auto handler = [&art](Node &node) {
		const auto type = node.GetType();
		switch (type) {
		case NType::LEAF_INLINED:
			node.Clear();
			return ARTHandlingResult::NONE;
		case NType::LEAF:
			Leaf::DeprecatedFree(art, node);
			return ARTHandlingResult::NONE;
		case NType::NODE_7_LEAF:
		case NType::NODE_15_LEAF:
		case NType::NODE_256_LEAF:
		case NType::PREFIX:
		case NType::NODE_4:
		case NType::NODE_16:
		case NType::NODE_48:
		case NType::NODE_256:
			break;
		default:
			throw InternalException("invalid node type for Free: %d", type);
		}

		FreeNode(art, node);
		return ARTHandlingResult::NONE;
	};

	ARTScanner<ARTScanHandling::POP, Node> scanner(art, handler, node);
	scanner.Scan(handler);
}

//===--------------------------------------------------------------------===//
// Allocators
//===--------------------------------------------------------------------===//

FixedSizeAllocator &Node::GetAllocator(const ART &art, const NType type) {
	return *(*art.allocators)[GetAllocatorIdx(type)];
}

uint8_t Node::GetAllocatorIdx(const NType type) {
	switch (type) {
	case NType::PREFIX:
		return 0;
	case NType::LEAF:
		return 1;
	case NType::NODE_4:
		return 2;
	case NType::NODE_16:
		return 3;
	case NType::NODE_48:
		return 4;
	case NType::NODE_256:
		return 5;
	case NType::NODE_7_LEAF:
		return 6;
	case NType::NODE_15_LEAF:
		return 7;
	case NType::NODE_256_LEAF:
		return 8;
	default:
		throw InternalException("Invalid node type for GetAllocatorIdx: %d.", type);
	}
}

//===--------------------------------------------------------------------===//
// Inserts
//===--------------------------------------------------------------------===//

void Node::ReplaceChild(const ART &art, const uint8_t byte, const Node child) const {
	D_ASSERT(HasMetadata());

	auto type = GetType();
	switch (type) {
	case NType::NODE_4:
		return Node4::ReplaceChild(Ref<Node4>(art, *this, type), byte, child);
	case NType::NODE_16:
		return Node16::ReplaceChild(Ref<Node16>(art, *this, type), byte, child);
	case NType::NODE_48:
		return Ref<Node48>(art, *this, type).ReplaceChild(byte, child);
	case NType::NODE_256:
		return Ref<Node256>(art, *this, type).ReplaceChild(byte, child);
	default:
		throw InternalException("Invalid node type for ReplaceChild: %d.", type);
	}
}

void Node::InsertChild(ART &art, Node &node, const uint8_t byte, const Node child) {
	D_ASSERT(node.HasMetadata());

	auto type = node.GetType();
	switch (type) {
	case NType::NODE_4:
		return Node4::InsertChild(art, node, byte, child);
	case NType::NODE_16:
		return Node16::InsertChild(art, node, byte, child);
	case NType::NODE_48:
		return Node48::InsertChild(art, node, byte, child);
	case NType::NODE_256:
		return Node256::InsertChild(art, node, byte, child);
	case NType::NODE_7_LEAF:
		return Node7Leaf::InsertByte(art, node, byte);
	case NType::NODE_15_LEAF:
		return Node15Leaf::InsertByte(art, node, byte);
	case NType::NODE_256_LEAF:
		return Node256Leaf::InsertByte(art, node, byte);
	default:
		throw InternalException("Invalid node type for InsertChild: %d.", type);
	}
}

//===--------------------------------------------------------------------===//
// Delete
//===--------------------------------------------------------------------===//

void Node::DeleteChild(ART &art, Node &node, Node &prefix, const uint8_t byte, const GateStatus status,
                       const ARTKey &row_id) {
	D_ASSERT(node.HasMetadata());

	auto type = node.GetType();
	switch (type) {
	case NType::NODE_4:
		return Node4::DeleteChild(art, node, prefix, byte, status);
	case NType::NODE_16:
		return Node16::DeleteChild(art, node, byte);
	case NType::NODE_48:
		return Node48::DeleteChild(art, node, byte);
	case NType::NODE_256:
		return Node256::DeleteChild(art, node, byte);
	case NType::NODE_7_LEAF:
		return Node7Leaf::DeleteByte(art, node, prefix, byte, row_id);
	case NType::NODE_15_LEAF:
		return Node15Leaf::DeleteByte(art, node, byte);
	case NType::NODE_256_LEAF:
		return Node256Leaf::DeleteByte(art, node, byte);
	default:
		throw InternalException("Invalid node type for DeleteChild: %d.", type);
	}
}

//===--------------------------------------------------------------------===//
// Get child and byte.
//===--------------------------------------------------------------------===//

template <class NODE>
static unsafe_optional_ptr<Node> GetChildInternal(ART &art, NODE &node, const uint8_t byte, const bool unsafe) {
	D_ASSERT(node.HasMetadata());

	auto type = node.GetType();
	switch (type) {
	case NType::NODE_4:
		return Node4::GetChild(Node::Ref<Node4>(art, node, type), byte, unsafe);
	case NType::NODE_16:
		return Node16::GetChild(Node::Ref<Node16>(art, node, type), byte, unsafe);
	case NType::NODE_48:
		return Node48::GetChild(Node::Ref<Node48>(art, node, type), byte, unsafe);
	case NType::NODE_256: {
		return Node256::GetChild(Node::Ref<Node256>(art, node, type), byte, unsafe);
	}
	default:
		throw InternalException("Invalid node type for GetChildInternal: %d.", type);
	}
}

const unsafe_optional_ptr<Node> Node::GetChild(ART &art, const uint8_t byte) const {
	return GetChildInternal(art, *this, byte, false);
}

unsafe_optional_ptr<Node> Node::GetChildMutable(ART &art, const uint8_t byte, const bool unsafe) const {
	return GetChildInternal(art, *this, byte, unsafe);
}

template <class NODE>
unsafe_optional_ptr<Node> GetNextChildInternal(ART &art, NODE &node, uint8_t &byte) {
	D_ASSERT(node.HasMetadata());

	auto type = node.GetType();
	switch (type) {
	case NType::NODE_4:
		return Node4::GetNextChild(Node::Ref<Node4>(art, node, type), byte);
	case NType::NODE_16:
		return Node16::GetNextChild(Node::Ref<Node16>(art, node, type), byte);
	case NType::NODE_48:
		return Node48::GetNextChild(Node::Ref<Node48>(art, node, type), byte);
	case NType::NODE_256:
		return Node256::GetNextChild(Node::Ref<Node256>(art, node, type), byte);
	default:
		throw InternalException("Invalid node type for GetNextChildInternal: %d.", type);
	}
}

const unsafe_optional_ptr<Node> Node::GetNextChild(ART &art, uint8_t &byte) const {
	return GetNextChildInternal(art, *this, byte);
}

bool Node::HasByte(ART &art, const uint8_t byte) const {
	D_ASSERT(HasMetadata());

	auto type = GetType();
	switch (type) {
	case NType::NODE_7_LEAF:
		return Ref<const Node7Leaf>(art, *this, NType::NODE_7_LEAF).HasByte(byte);
	case NType::NODE_15_LEAF:
		return Ref<const Node15Leaf>(art, *this, NType::NODE_15_LEAF).HasByte(byte);
	case NType::NODE_256_LEAF:
		return Ref<Node256Leaf>(art, *this, NType::NODE_256_LEAF).HasByte(byte);
	default:
		throw InternalException("Invalid node type for GetNextByte: %d.", type);
	}
}

bool Node::GetNextByte(ART &art, uint8_t &byte) const {
	D_ASSERT(HasMetadata());

	auto type = GetType();
	switch (type) {
	case NType::NODE_7_LEAF:
		return Ref<const Node7Leaf>(art, *this, NType::NODE_7_LEAF).GetNextByte(byte);
	case NType::NODE_15_LEAF:
		return Ref<const Node15Leaf>(art, *this, NType::NODE_15_LEAF).GetNextByte(byte);
	case NType::NODE_256_LEAF:
		return Ref<Node256Leaf>(art, *this, NType::NODE_256_LEAF).GetNextByte(byte);
	default:
		throw InternalException("Invalid node type for GetNextByte: %d.", type);
	}
}

//===--------------------------------------------------------------------===//
// Utility
//===--------------------------------------------------------------------===//

idx_t GetCapacity(NType type) {
	switch (type) {
	case NType::NODE_4:
		return Node4::CAPACITY;
	case NType::NODE_7_LEAF:
		return Node7Leaf::CAPACITY;
	case NType::NODE_15_LEAF:
		return Node15Leaf::CAPACITY;
	case NType::NODE_16:
		return Node16::CAPACITY;
	case NType::NODE_48:
		return Node48::CAPACITY;
	case NType::NODE_256_LEAF:
		return Node256::CAPACITY;
	case NType::NODE_256:
		return Node256::CAPACITY;
	default:
		throw InternalException("Invalid node type for GetCapacity: %d.", type);
	}
}

NType Node::GetNodeType(idx_t count) {
	if (count <= Node4::CAPACITY) {
		return NType::NODE_4;
	} else if (count <= Node16::CAPACITY) {
		return NType::NODE_16;
	} else if (count <= Node48::CAPACITY) {
		return NType::NODE_48;
	}
	return NType::NODE_256;
}

bool Node::IsNode() const {
	switch (GetType()) {
	case NType::NODE_4:
	case NType::NODE_16:
	case NType::NODE_48:
	case NType::NODE_256:
		return true;
	default:
		return false;
	}
}

bool Node::IsLeafNode() const {
	switch (GetType()) {
	case NType::NODE_7_LEAF:
	case NType::NODE_15_LEAF:
	case NType::NODE_256_LEAF:
		return true;
	default:
		return false;
	}
}

bool Node::IsAnyLeaf() const {
	if (IsLeafNode()) {
		return true;
	}

	switch (GetType()) {
	case NType::LEAF_INLINED:
	case NType::LEAF:
		return true;
	default:
		return false;
	}
}

//===--------------------------------------------------------------------===//
// TransformToDeprecated
//===--------------------------------------------------------------------===//

template <class NODE>
static void TransformToDeprecatedPushChildren(ART &art, Node &node, NType type, vector<reference<Node>> &stack) {
	auto ptr = Node::InMemoryRef<NODE>(art, node, type);
	if (ptr) {
		NODE::Iterator(*ptr, [&](Node &child) { stack.emplace_back(child); });
	}
}

void Node::TransformToDeprecated(ART &art, Node &node, TransformToDeprecatedState &state) {
	vector<reference<Node>> stack;
	stack.emplace_back(node);

	while (!stack.empty()) {
		Node &current = stack.back().get();
		stack.pop_back();

		D_ASSERT(current.HasMetadata());

		if (current.GetGateStatus() == GateStatus::GATE_SET) {
			D_ASSERT(current.GetType() != NType::LEAF_INLINED);
			Leaf::TransformToDeprecated(art, current);
			continue;
		}

		auto type = current.GetType();
		switch (type) {
		case NType::PREFIX: {
			auto child = PrefixHandle::TransformToDeprecated(art, current, state);
			if (child) {
				stack.emplace_back(*child);
			}
			break;
		}
		case NType::LEAF_INLINED:
		case NType::LEAF:
			break;
		case NType::NODE_4:
			TransformToDeprecatedPushChildren<Node4>(art, current, type, stack);
			break;
		case NType::NODE_16:
			TransformToDeprecatedPushChildren<Node16>(art, current, type, stack);
			break;
		case NType::NODE_48:
			TransformToDeprecatedPushChildren<Node48>(art, current, type, stack);
			break;
		case NType::NODE_256:
			TransformToDeprecatedPushChildren<Node256>(art, current, type, stack);
			break;
		default:
			throw InternalException("invalid node type for TransformToDeprecated: %d", type);
		}
	}
}

//===--------------------------------------------------------------------===//
// Verification
//===--------------------------------------------------------------------===//

void Node::Verify(ART &art) const {
	D_ASSERT(HasMetadata());

	auto type = GetType();
	switch (type) {
	case NType::LEAF_INLINED:
		return;
	case NType::LEAF:
		Leaf::DeprecatedVerify(art, *this);
		return;
	case NType::PREFIX: {
		ConstPrefixHandle::Verify(art, *this);
		return;
	}
	default:
		break;
	}

	if (!IsLeafNode()) {
		uint8_t byte = 0;
		auto child = GetNextChild(art, byte);
		while (child) {
			child->Verify(art);
			if (byte == NumericLimits<uint8_t>::Maximum()) {
				break;
			}
			byte++;
			child = GetNextChild(art, byte);
		}
	}
}

void Node::VerifyAllocations(ART &art, unordered_map<uint8_t, idx_t> &node_counts) const {
	D_ASSERT(HasMetadata());

	auto handler = [&art, &node_counts](const Node &node) {
		ARTHandlingResult result;
		const auto type = node.GetType();
		switch (type) {
		case NType::LEAF_INLINED:
			return ARTHandlingResult::SKIP;
		case NType::LEAF: {
			auto &leaf = Ref<Leaf>(art, node, type);
			leaf.DeprecatedVerifyAllocations(art, node_counts);
			return ARTHandlingResult::SKIP;
		}
		case NType::NODE_7_LEAF:
		case NType::NODE_15_LEAF:
		case NType::NODE_256_LEAF: {
			result = ARTHandlingResult::SKIP;
			break;
		}
		case NType::PREFIX:
		case NType::NODE_4:
		case NType::NODE_16:
		case NType::NODE_48:
		case NType::NODE_256: {
			result = ARTHandlingResult::CONTINUE;
			break;
		}
		default:
			throw InternalException("invalid node type for VerifyAllocations: %d", type);
		}
		node_counts[GetAllocatorIdx(type)]++;
		return result;
	};

	ARTScanner<ARTScanHandling::EMPLACE, const Node> scanner(art, handler, *this);
	scanner.Scan(handler);
}

//===--------------------------------------------------------------------===//
// Printing
//===--------------------------------------------------------------------===//

string Node::ToString(ART &art, const ToStringOptions &options) const {
	auto indent = [](string &str, const idx_t n) {
		str.append(n, ' ');
	};
	// if inside gate, print byte values not ascii.
	auto format_byte = [&](uint8_t byte) {
		if (!options.inside_gate && options.display_ascii && byte >= 32 && byte <= 126) {
			return string(1, static_cast<char>(byte));
		}
		return to_string(byte);
	};
	auto type = GetType();
	bool is_gate = GetGateStatus() == GateStatus::GATE_SET;
	bool propagate_gate = options.inside_gate || is_gate;

	bool print_full_tree = propagate_gate || !options.key_path || options.depth_remaining == 0;

	switch (type) {
	case NType::LEAF_INLINED: {
		string str = "";
		indent(str, options.indent_level);
		return str + "Inlined Leaf [row ID: " + to_string(GetRowId()) + "]\n";
	}
	case NType::LEAF: {
		ToStringOptions leaf_options = options;
		return Leaf::DeprecatedToString(art, *this, leaf_options);
	}
	case NType::PREFIX: {
		ToStringOptions prefix_options = options;
		prefix_options.inside_gate = propagate_gate;
		string str = ConstPrefixHandle::ToString(art, *this, prefix_options);
		if (is_gate) {
			string s = "";
			indent(s, options.indent_level);
			s += "Gate\n";
			return s + str;
		}
		string s = "";
		return s + str;
	}
	default:
		break;
	}
	string str = "";
	indent(str, options.indent_level);
	str = str + "Node" + to_string(GetCapacity(type)) += "\n";
	uint8_t byte = 0;

	if (IsLeafNode()) {
		indent(str, options.indent_level);
		str += "Leaf |";
		auto has_byte = GetNextByte(art, byte);
		while (has_byte) {
			str += format_byte(byte) + "|";
			if (byte == NumericLimits<uint8_t>::Maximum()) {
				break;
			}
			byte++;
			has_byte = GetNextByte(art, byte);
		}
		str += "\n";
	} else {
		uint8_t expected_byte = 0;
		bool has_expected_byte = false;
		if (options.key_path && !print_full_tree && options.key_depth < options.key_path->len) {
			expected_byte = (*options.key_path)[options.key_depth];
			has_expected_byte = true;
		}

		uint8_t byte = 0;
		auto child = GetNextChild(art, byte);
		while (child) {
			// Determine if this child is on the path to the key_path
			// If we have an expected byte, only traverse the matching child
			// If we don't have an expected byte, we're printing the full tree, so all children are on_path.
			bool on_path = !has_expected_byte || (has_expected_byte && byte == expected_byte);
			if (on_path) {
				ToStringOptions child_options = options;
				child_options.indent_level = options.indent_level + options.indent_amount;
				child_options.inside_gate = propagate_gate;
				child_options.key_depth = has_expected_byte ? options.key_depth + 1 : options.key_depth;
				child_options.depth_remaining = (options.depth_remaining > 0) ? options.depth_remaining - 1 : 0;
				string c = child->ToString(art, child_options);
				indent(str, options.indent_level);
				str = str + format_byte(byte) + ",\n" + c;
			} else {
				// If we have an expected byte, but the current byte is not the expected byte.
				// In this case we check if we are only printing the structure, in which case we skip printing the
				// child byte.
				if (!options.structure_only) {
					indent(str, options.indent_level);
					str = str + format_byte(byte) + ", [not printed]\n";
				}
			}
			byte++;
			child = GetNextChild(art, byte);
			if (byte == NumericLimits<uint8_t>::Maximum()) {
				break;
			}
		}
	}

	if (is_gate) {
		string s = "";
		indent(s, options.indent_level + options.indent_amount);
		str = "Gate\n" + s + str;
	}
	return str;
}

} // namespace duckdb




namespace duckdb {

void Node256::InsertChild(ART &art, Node &node, const uint8_t byte, const Node child) {
	NodeHandle<Node256> handle(art, node);
	auto &n = handle.Get();
	n.count++;
	n.children[byte] = child;
}

void Node256::DeleteChild(ART &art, Node &node, const uint8_t byte) {
	{
		NodeHandle<Node256> handle(art, node);
		auto &n = handle.Get();

		// Free the child and decrease the count.
		Node::FreeTree(art, n.children[byte]);
		n.count--;

		if (n.count > SHRINK_THRESHOLD) {
			return;
		}
	}

	// Shrink to Node48.
	auto node256 = node;
	Node48::ShrinkNode256(art, node, node256);
}

void Node256::GrowNode48(ART &art, Node &node256, Node &node48) {
	{
		NodeHandle<Node48> n48_handle(art, node48);
		auto &n48 = n48_handle.Get();

		auto n256_handle = New(art, node256);
		auto &n256 = n256_handle.Get();
		node256.SetGateStatus(node48.GetGateStatus());

		n256.count = n48.count;
		for (uint16_t i = 0; i < CAPACITY; i++) {
			if (n48.child_index[i] != Node48::EMPTY_MARKER) {
				n256.children[i] = n48.children[n48.child_index[i]];
			}
		}
	}
	Node::FreeNode(art, node48);
}

} // namespace duckdb





namespace duckdb {

NodeHandle<Node256Leaf> Node256Leaf::New(ART &art, Node &node) {
	node = Node::GetAllocator(art, NODE_256_LEAF).New();
	node.SetMetadata(static_cast<uint8_t>(NODE_256_LEAF));

	NodeHandle<Node256Leaf> handle(art, node);
	auto &n = handle.Get();

	n.count = 0;
	ValidityMask mask(&n.mask[0], Node256::CAPACITY);
	mask.SetAllInvalid(CAPACITY);

	return handle;
}

void Node256Leaf::InsertByte(ART &art, Node &node, const uint8_t byte) {
	NodeHandle<Node256Leaf> handle(art, node);
	auto &n = handle.Get();

	n.count++;
	ValidityMask mask(&n.mask[0], Node256::CAPACITY);
	mask.SetValid(byte);
}

void Node256Leaf::DeleteByte(ART &art, Node &node, const uint8_t byte) {
	{
		NodeHandle<Node256Leaf> handle(art, node);
		auto &n = handle.Get();

		n.count--;
		ValidityMask mask(&n.mask[0], Node256::CAPACITY);
		mask.SetInvalid(byte);

		if (n.count > Node48::SHRINK_THRESHOLD) {
			return;
		}
	}
	// Shrink node to Node15.
	auto node256 = node;
	Node15Leaf::ShrinkNode256Leaf(art, node, node256);
}

bool Node256Leaf::HasByte(const uint8_t byte) {
	ValidityMask v_mask(&mask[0], Node256::CAPACITY);
	return v_mask.RowIsValid(byte);
}

array_ptr<uint8_t> Node256Leaf::GetBytes(ArenaAllocator &arena) {
	auto mem = arena.AllocateAligned(sizeof(uint8_t) * count);
	array_ptr<uint8_t> bytes(mem, count);

	ValidityMask v_mask(&mask[0], Node256::CAPACITY);
	uint16_t ptr_idx = 0;
	for (uint16_t i = 0; i < CAPACITY; i++) {
		if (v_mask.RowIsValid(i)) {
			bytes[ptr_idx++] = UnsafeNumericCast<uint8_t>(i);
		}
	}

	return bytes;
}

bool Node256Leaf::GetNextByte(uint8_t &byte) {
	ValidityMask v_mask(&mask[0], Node256::CAPACITY);
	for (uint16_t i = byte; i < CAPACITY; i++) {
		if (v_mask.RowIsValid(i)) {
			byte = UnsafeNumericCast<uint8_t>(i);
			return true;
		}
	}

	return false;
}

void Node256Leaf::GrowNode15Leaf(ART &art, Node &node256_leaf, Node &node15_leaf) {
	{
		NodeHandle<Node15Leaf> n15_handle(art, node15_leaf);
		auto &n15 = n15_handle.Get();

		auto n256_handle = New(art, node256_leaf);
		auto &n256 = n256_handle.Get();
		node256_leaf.SetGateStatus(node15_leaf.GetGateStatus());

		n256.count = n15.count;
		ValidityMask mask(&n256.mask[0], Node256::CAPACITY);
		for (uint8_t i = 0; i < n15.count; i++) {
			mask.SetValid(n15.key[i]);
		}
	}
	Node::FreeNode(art, node15_leaf);
}

} // namespace duckdb





namespace duckdb {

void Node48::InsertChild(ART &art, Node &node, const uint8_t byte, const Node child) {
	{
		NodeHandle<Node48> handle(art, node);
		auto &n = handle.Get();

		if (n.count != CAPACITY) {
			// Still space. Insert the child.
			// Find an empty position in the node list.
			auto child_pos = n.count;
			if (n.children[child_pos].HasMetadata()) {
				child_pos = 0;
				while (n.children[child_pos].HasMetadata()) {
					child_pos++;
				}
			}

			n.children[child_pos] = child;
			n.child_index[byte] = child_pos;
			n.count++;
			return;
		}
	}

	// The node is full.
	// Grow to Node256.
	auto node48 = node;
	Node256::GrowNode48(art, node, node48);
	Node256::InsertChild(art, node, byte, child);
}

void Node48::DeleteChild(ART &art, Node &node, const uint8_t byte) {
	{
		NodeHandle<Node48> handle(art, node);
		auto &n = handle.Get();

		// Free the child and decrease the count.
		Node::FreeTree(art, n.children[n.child_index[byte]]);
		n.child_index[byte] = EMPTY_MARKER;
		n.count--;

		if (n.count >= SHRINK_THRESHOLD) {
			return;
		}
	}

	// Shrink to Node16.
	auto node48 = node;
	Node16::ShrinkNode48(art, node, node48);
}

void Node48::GrowNode16(ART &art, Node &node48, Node &node16) {
	{
		NodeHandle<Node16> n16_handle(art, node16);
		auto &n16 = n16_handle.Get();

		auto n48_handle = New(art, node48);
		auto &n48 = n48_handle.Get();
		node48.SetGateStatus(node16.GetGateStatus());

		n48.count = n16.count;
		for (uint8_t i = 0; i < n16.count; i++) {
			n48.child_index[n16.key[i]] = i;
			n48.children[i] = n16.children[i];
		}
	}
	Node::FreeNode(art, node16);
}

void Node48::ShrinkNode256(ART &art, Node &node48, Node &node256) {
	{
		auto n48_handle = New(art, node48);
		auto &n48 = n48_handle.Get();
		node48.SetGateStatus(node256.GetGateStatus());

		NodeHandle<Node256> n256_handle(art, node256);
		auto &n256 = n256_handle.Get();

		n48.count = 0;
		for (uint16_t i = 0; i < Node256::CAPACITY; i++) {
			if (!n256.children[i].HasMetadata()) {
				continue;
			}
			n48.child_index[i] = n48.count;
			n48.children[n48.count] = n256.children[i];
			n48.count++;
		}
	}
	Node::FreeNode(art, node256);
}

} // namespace duckdb










namespace duckdb {

Prefix::Prefix(const ART &art, const Node ptr_p, const bool is_mutable, const bool set_in_memory) {
	if (!set_in_memory) {
		data = Node::GetAllocator(art, PREFIX).Get(ptr_p, is_mutable);
	} else {
		data = Node::GetAllocator(art, PREFIX).GetIfLoaded(ptr_p);
		if (!data) {
			ptr = nullptr;
			in_memory = false;
			return;
		}
	}
	ptr = reinterpret_cast<Node *>(data + art.PrefixCount() + 1);
	in_memory = true;
}

Prefix::Prefix(FixedSizeAllocator &allocator, const Node ptr_p, const idx_t count) {
	data = allocator.Get(ptr_p, true);
	ptr = reinterpret_cast<Node *>(data + count + 1);
	in_memory = true;
}

uint8_t Prefix::GetByte(const ART &art, const Node &node, const uint8_t pos) {
	D_ASSERT(node.GetType() == PREFIX);
	Prefix prefix(art, node);
	return prefix.data[pos];
}

Prefix Prefix::NewInternal(ART &art, Node &node, const data_ptr_t data, const uint8_t count, const idx_t offset) {
	node = Node::GetAllocator(art, PREFIX).New();
	node.SetMetadata(static_cast<uint8_t>(PREFIX));

	Prefix prefix(art, node, true);
	prefix.data[art.PrefixCount()] = count;
	if (data) {
		D_ASSERT(count);
		memcpy(prefix.data, data + offset, count);
	}
	prefix.ptr->Clear();
	return prefix;
}

void Prefix::New(ART &art, reference<Node> &ref, const ARTKey &key, const idx_t depth, idx_t count) {
	idx_t offset = 0;

	while (count) {
		auto min = MinValue(UnsafeNumericCast<idx_t>(art.PrefixCount()), count);
		auto this_count = UnsafeNumericCast<uint8_t>(min);
		auto prefix = NewInternal(art, ref, key.data, this_count, offset + depth);

		ref = *prefix.ptr;
		offset += this_count;
		count -= this_count;
	}
}

void Prefix::Concat(ART &art, Node &parent, Node &node4, const Node child, uint8_t byte, const GateStatus node4_status,
                    const GateStatus status) {
	// We have four situations from which we enter here:
	// 1: PREFIX (parent) - Node4 (prev_node4) - PREFIX (child) - INLINED_LEAF, or
	// 2: PREFIX (parent) - Node4 (prev_node4) - INLINED_LEAF (child), or
	// 3: Node (parent) - Node4 (prev_node4) - PREFIX (child) - INLINED_LEAF, or
	// 4: Node (parent) - Node4 (prev_node4) - INLINED_LEAF (child).

	D_ASSERT(!parent.IsAnyLeaf());
	D_ASSERT(child.HasMetadata());

	// The Node4 was a gate.
	if (node4_status == GateStatus::GATE_SET) {
		D_ASSERT(parent.GetGateStatus() == GateStatus::GATE_NOT_SET);
		D_ASSERT(child.GetGateStatus() == GateStatus::GATE_NOT_SET);
		ConcatNode4WasGate(art, node4, child, byte);
		return;
	}

	// The child is a gate.
	if (child.GetGateStatus() == GateStatus::GATE_SET) {
		D_ASSERT(node4_status == GateStatus::GATE_NOT_SET);
		ConcatChildIsGate(art, parent, node4, child, byte);
		return;
	}
	ConcatInternal(art, parent, node4, child, byte, status);
}

void Prefix::Reduce(ART &art, Node &node, const idx_t pos) {
	D_ASSERT(node.HasMetadata());
	D_ASSERT(pos < art.PrefixCount());

	// We always reduce by at least one byte,
	// thus, if the prefix was a gate, it no longer is.
	node.SetGateStatus(GateStatus::GATE_NOT_SET);

	Prefix prefix(art, node);
	if (pos == idx_t(prefix.data[art.PrefixCount()] - 1)) {
		auto next = *prefix.ptr;
		Node::FreeNode(art, node);
		node = next;
		return;
	}

	// FIXME: Copy into new prefix (chain) instead of shifting.
	for (idx_t i = 0; i < art.PrefixCount() - pos - 1; i++) {
		prefix.data[i] = prefix.data[pos + i + 1];
	}

	prefix.data[art.PrefixCount()] -= pos + 1;
	prefix.Append(art, *prefix.ptr);
}

GateStatus Prefix::Split(ART &art, reference<Node> &node, Node &child, const uint8_t pos) {
	D_ASSERT(node.get().HasMetadata());

	Prefix prefix(art, node, true);

	// The split is at the last prefix byte, and the prefix is full.
	// We decrease the count and return.
	// We get:
	// [this prefix minus its last byte] ->
	// [new node at split byte] ->
	// [child at split byte: prefix.ptr].
	if (pos + 1 == art.PrefixCount()) {
		prefix.data[art.PrefixCount()]--;
		node = *prefix.ptr;
		child = *prefix.ptr;
		return GateStatus::GATE_NOT_SET;
	}

	if (pos + 1 < prefix.data[art.PrefixCount()]) {
		// The split is not at the last prefix byte.
		// We get:
		// [this prefix minus split byte, minus remaining bytes] ->
		// [new node at split byte] ->
		// [child with remaining bytes, and possibly remaining prefix nodes].

		// Create a new prefix and
		// 1. copy the remaining bytes of this prefix.
		// 2. append remaining prefix nodes.
		auto new_prefix = NewInternal(art, child, nullptr, 0, 0);
		new_prefix.data[art.PrefixCount()] = prefix.data[art.PrefixCount()] - pos - 1;
		memcpy(new_prefix.data, prefix.data + pos + 1, new_prefix.data[art.PrefixCount()]);

		if (prefix.ptr->GetType() == PREFIX && prefix.ptr->GetGateStatus() == GateStatus::GATE_NOT_SET) {
			new_prefix.Append(art, *prefix.ptr);
		} else {
			*new_prefix.ptr = *prefix.ptr;
		}

	} else {
		D_ASSERT(pos + 1 == prefix.data[art.PrefixCount()]);
		// The split is at the last prefix byte, but the prefix is not full.
		// There are no other bytes or prefixes after the split.
		// We get:
		// [this prefix minus split byte (can be its only byte, then we free it)] ->
		// [new node at split byte] ->
		// [child at split byte: prefix.ptr].
		child = *prefix.ptr;
	}

	// Set the new count of this node (can be empty).
	prefix.data[art.PrefixCount()] = pos;

	// No bytes left before the split, free this node.
	if (pos == 0) {
		auto old_status = node.get().GetGateStatus();
		Node::FreeNode(art, node);
		return old_status;
	}

	// There are bytes left before the split.
	// The subsequent node replaces the split byte.
	node = *prefix.ptr;
	return GateStatus::GATE_NOT_SET;
}

Prefix Prefix::Append(ART &art, const uint8_t byte) {
	if (data[art.PrefixCount()] != art.PrefixCount()) {
		data[data[art.PrefixCount()]] = byte;
		data[art.PrefixCount()]++;
		return *this;
	}

	auto prefix = NewInternal(art, *ptr, nullptr, 0, 0);
	return prefix.Append(art, byte);
}

void Prefix::Append(ART &art, Node other) {
	D_ASSERT(other.HasMetadata());

	Prefix prefix = *this;
	while (other.GetType() == PREFIX) {
		if (other.GetGateStatus() == GateStatus::GATE_SET) {
			*prefix.ptr = other;
			return;
		}

		Prefix other_prefix(art, other, true);
		for (idx_t i = 0; i < other_prefix.data[art.PrefixCount()]; i++) {
			prefix = prefix.Append(art, other_prefix.data[i]);
		}

		*prefix.ptr = *other_prefix.ptr;
		Node::FreeNode(art, other);
		other = *prefix.ptr;
	}
}

Prefix Prefix::GetTail(ART &art, const Node &node) {
	Prefix prefix(art, node, true);
	while (prefix.ptr->GetType() == PREFIX) {
		prefix = Prefix(art, *prefix.ptr, true);
	}
	return prefix;
}

void Prefix::ConcatInternal(ART &art, Node &parent, Node &node4, const Node child, uint8_t byte,
                            const GateStatus status) {
	if (child.GetType() == NType::LEAF_INLINED) {
		if (status == GateStatus::GATE_SET) {
			if (parent.GetType() == NType::PREFIX) {
				// The parent only contained the Node4, so we can now inline 'all the way up',
				// and the gate is no longer nested.
				while (parent.GetType() == NType::PREFIX) {
					Prefix prefix(art, parent, true);
					auto temp = *prefix.ptr;
					Node::FreeNode(art, parent);
					parent = temp;
				}
				parent = child;
				return;
			}
			// The parent is any node inside the gate.
			// Inside gates, inlined row IDs are not prefixed,
			// so we directly inline into the previous Node4.
			node4 = child;
			return;
		}

		// Not inside a gate.
		if (parent.GetType() == NType::PREFIX) {
			// Append the byte to the prefix, and then inline the child.
			auto tail = GetTail(art, parent);
			tail = tail.Append(art, byte);
			*tail.ptr = child;
			return;
		}

		auto prefix = NewInternal(art, node4, &byte, 1, 0);
		*prefix.ptr = child;
		return;
	}

	// The child is not inlined.
	if (parent.GetType() == NType::PREFIX) {
		// Append the byte to the prefix.
		auto tail = GetTail(art, parent);
		tail = tail.Append(art, byte);

		// Append the child to the prefix.
		if (child.GetType() == NType::PREFIX) {
			tail.Append(art, child);
			return;
		}
		*tail.ptr = child;
		return;
	}

	// The child is not inlined, and the parent is not a prefix.
	auto prefix = NewInternal(art, node4, &byte, 1, 0);
	if (child.GetType() == NType::PREFIX) {
		prefix.Append(art, child);
		return;
	}
	*prefix.ptr = child;
}

void Prefix::ConcatNode4WasGate(ART &art, Node &node4, const Node child, uint8_t byte) {
	D_ASSERT(child.HasMetadata());

	if (child.GetType() == NType::LEAF_INLINED) {
		// Inside gates, inlined row IDs are not prefixed.
		// The child is inlined, so we inline into the previous Node4.
		// There is no longer a nested leaf.
		node4 = child;
		return;
	}

	if (child.GetType() == PREFIX) {
		// At least one more row ID in this gate and the child is a prefix.
		// We create a new prefix of length one containing the remaining byte.
		// Then, we append the child prefix.
		auto prefix = NewInternal(art, node4, &byte, 1, 0);
		prefix.ptr->Clear();
		prefix.Append(art, child);
		node4.SetGateStatus(GateStatus::GATE_SET);
		return;
	}
	// At least one more row ID in this gate and the child is not a prefix.
	// We create a new prefix of length one containing the remaining byte.
	// then, we append the child.
	auto prefix = NewInternal(art, node4, &byte, 1, 0);
	*prefix.ptr = child;
	node4.SetGateStatus(GateStatus::GATE_SET);
}

void Prefix::ConcatChildIsGate(ART &art, Node &parent, Node &node4, const Node child, uint8_t byte) {
	if (parent.GetType() != PREFIX) {
		// Create a new prefix at the former position of the Node4,
		// and point it to the gate.
		auto prefix = NewInternal(art, node4, &byte, 1, 0);
		*prefix.ptr = child;
		return;
	}

	// The parent is a prefix (chain), so we need to append the byte to its tail.
	auto tail = GetTail(art, parent);
	tail = tail.Append(art, byte);
	*tail.ptr = child;
}

Prefix Prefix::TransformToDeprecatedAppend(ART &art, FixedSizeAllocator &allocator, uint8_t byte) {
	if (data[DEPRECATED_COUNT] != DEPRECATED_COUNT) {
		data[data[DEPRECATED_COUNT]] = byte;
		data[DEPRECATED_COUNT]++;
		return *this;
	}

	*ptr = allocator.New();
	ptr->SetMetadata(static_cast<uint8_t>(PREFIX));
	Prefix prefix(allocator, *ptr, DEPRECATED_COUNT);
	return prefix.TransformToDeprecatedAppend(art, allocator, byte);
}

} // namespace duckdb





namespace duckdb {

PrefixHandle::PrefixHandle(const ART &art, const Node node)
    : segment_handle(Node::GetAllocator(art, PREFIX).GetHandle(node)) {
	data = segment_handle.GetPtr();
	child = reinterpret_cast<Node *>(data + art.PrefixCount() + 1);
	segment_handle.MarkModified();
}

PrefixHandle::PrefixHandle(FixedSizeAllocator &allocator, const Node node, const uint8_t count)
    : segment_handle(allocator.GetHandle(node)) {
	data = segment_handle.GetPtr();
	child = reinterpret_cast<Node *>(data + count + 1);
	segment_handle.MarkModified();
}

PrefixHandle::PrefixHandle(PrefixHandle &&other) noexcept
    : data(other.data), child(other.child), segment_handle(std::move(other.segment_handle)) {
	other.data = nullptr;
	other.child = nullptr;
}

PrefixHandle &PrefixHandle::operator=(PrefixHandle &&other) noexcept {
	if (this != &other) {
		// old segment handle reader count gets decremented on this move.
		segment_handle = std::move(other.segment_handle);

		data = other.data;
		child = other.child;

		other.data = nullptr;
		other.child = nullptr;
	}
	return *this;
}

PrefixHandle PrefixHandle::NewDeprecated(FixedSizeAllocator &allocator, Node &node) {
	node = allocator.New();
	node.SetMetadata(static_cast<uint8_t>(PREFIX));

	PrefixHandle handle(allocator, node, DEPRECATED_COUNT);
	handle.data[DEPRECATED_COUNT] = 0;
	return handle;
}

optional_ptr<Node> PrefixHandle::TransformToDeprecated(ART &art, Node &node, TransformToDeprecatedState &state) {
	// Early-out, if we do not need any transformations.
	if (!state.HasAllocator()) {
		reference<Node> ref(node);
		auto &allocator = Node::GetAllocator(art, PREFIX);
		while (ref.get().GetType() == PREFIX && ref.get().GetGateStatus() == GateStatus::GATE_NOT_SET) {
			if (!allocator.LoadedFromStorage(ref)) {
				return nullptr;
			}
			PrefixHandle handle(art, ref);
			ref = *handle.child;
		}
		return ref.get();
	}

	// We need to create a new prefix (chain) in the deprecated format.
	auto &deprecated_allocator = state.GetAllocator();
	Node new_node;
	auto new_handle = NewDeprecated(deprecated_allocator, new_node);

	auto &allocator = Node::GetAllocator(art, PREFIX);
	Node current_node = node;
	while (current_node.GetType() == PREFIX && current_node.GetGateStatus() == GateStatus::GATE_NOT_SET) {
		if (!allocator.LoadedFromStorage(current_node)) {
			return nullptr;
		}
		{
			// Decrease the readers on current_handle after moving all data over.
			PrefixHandle current_handle(art, current_node);
			for (idx_t i = 0; i < current_handle.data[art.PrefixCount()]; i++) {
				new_handle = new_handle.TransformToDeprecatedAppend(art, deprecated_allocator, current_handle.data[i]);
			}
			*new_handle.child = *current_handle.child;
		}

		// Freeing the node here can trigger a buffer removal (last segment on the buffer).
		// In that case, there cannot be any readers left on the buffer.
		Node::FreeNode(art, current_node);
		current_node = *new_handle.child;
	}

	node = new_node;
	return new_handle.child;
}

PrefixHandle PrefixHandle::TransformToDeprecatedAppend(ART &art, FixedSizeAllocator &allocator, const uint8_t byte) {
	if (data[DEPRECATED_COUNT] != DEPRECATED_COUNT) {
		data[data[DEPRECATED_COUNT]] = byte;
		data[DEPRECATED_COUNT]++;
		return std::move(*this);
	}

	auto new_prefix = NewDeprecated(allocator, *child);
	return new_prefix.TransformToDeprecatedAppend(art, allocator, byte);
}

} // namespace duckdb











