/**
 * \brief          The SHA-256 checkup routine.
 *
 * \return         \c 0 on success.
 * \return         \c 1 on failure.
 */
int mbedtls_sha256_self_test(int verbose);
#endif /* MBEDTLS_SHA256_C */

