    SHA1P(local.D, local.E, local.A, local.B, local.C, SHA1R(17));
    SHA1P(local.C, local.D, local.E, local.A, local.B, SHA1R(18));
    SHA1P(local.B, local.C, local.D, local.E, local.A, SHA1R(19));

